// A complete, runnable Go program — small by design.
package main

import "fmt"

func main() {
	// Go favors clarity over cleverness.
	goal := "simple, fast, reliable"
	fmt.Println("Go was built to be", goal)
}
// Output: Go was built to be simple, fast, reliable

// main.go
package main

import "fmt"

func main() {
	fmt.Println("served from one binary")
}

// Shell session:
// $ go build -o server .   # compile to a single executable
// $ ls -lh server
// -rwxr-xr-x  1 you  staff  1.9M server
// $ ./server              # no runtime to install — just run it
// served from one binary

package main

import "fmt"

func main() {
	x := 42          // type int, inferred by :=
	var name string = "Go" // explicit type declaration
	price := 9.99    // type float64, inferred

	// x = "oops"    // would NOT compile: cannot use string as int
	fmt.Printf("%T %T %T\n", x, name, price)
}
// Output: int string float64

// main.go
package main

import "fmt"

func main() {
	fmt.Println("hi from the toolchain")
}

// One command drives the whole workflow:
// $ go run main.go      # compile + run in one step
// hi from the toolchain
// $ go build ./...      # compile the module to a binary
// $ go test ./...       # run all tests
// $ go fmt ./...        # format every file canonically

// Messy but valid input (main.go):
// package main
// import "fmt"
// func main(){x:=1;y:=2
// fmt.Println( x+y )}

// $ gofmt -w main.go   # rewrites the file in canonical style

// Result — one true format, tab-indented:
package main

import "fmt"

func main() {
	x := 1
	y := 2
	fmt.Println(x + y) // => 3
}

package main

import (
	"fmt"
	"net/http" // a full HTTP server, straight from the stdlib
)

func main() {
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintln(w, "hello from net/http")
	})
	// Starts a real web server — no framework required.
	http.ListenAndServe(":8080", nil)
}
// $ curl localhost:8080  =>  hello from net/http

