package solution

import "fmt"

func Greet(name string) string {
	if name == "" {            // treat empty input as the default
		name = "world"
	}
	return fmt.Sprintf("Hello, %s!", name) // Sprintf builds a string
}

codeLab.testHarness:
package solution

import "testing"

func TestGreet(t *testing.T) {
	cases := []struct {
		in, want string
	}{
		{"Ada", "Hello, Ada!"},
		{"", "Hello, world!"},
	}
	for _, c := range cases {
		if got := Greet(c.in); got != c.want {
			t.Errorf("Greet(%q)=%q want %q", c.in, got, c.want)
		}
	}
}

