package main

import (
	"fmt"
	"net/http" // full HTTP server from the standard library
)

func main() {
	// Register a handler for the /ping route.
	http.HandleFunc("/ping", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "pong") // write the response body
	})
	// Start the server; blocks until it errors.
	http.ListenAndServe(":8080", nil)
}
